/**
 * The feature registry.  ** FROZEN — WRITTEN ONCE, NEVER EDITED AGAIN **
 *
 * ============================================================================
 *  DO NOT EDIT THIS FILE TO ADD YOUR FEATURE.
 *
 *  Create `apps/web/src/features/<your-slot-id>/register.ts` with a default
 *  export of `FeatureModule` and you are registered. Nothing else. The slot ids
 *  below are already declared; discovery is `import.meta.glob`, so adding a
 *  directory is the whole installation step and two agents can land two
 *  features in the same wave without touching one shared file (plan §5.2 /
 *  §A8 — the anti-collision rule that also produced the frozen topic barrel).
 *
 *      // apps/web/src/features/viewport/register.ts
 *      import { Viewport } from '@tenmol/viewport';
 *      import type { FeatureModule } from '../registry';
 *      export default { id: 'viewport', Panel: Viewport } satisfies FeatureModule;
 *
 *  A slot with no directory renders its `absent` note instead of a panel. That
 *  is deliberate: an unbuilt feature must be VISIBLY unbuilt, never a blank
 *  space that looks like it works.
 * ============================================================================
 *
 * The ids are the `apps/web/src/features/<name>/**` directories assigned in plan
 * §6, plus their owning work package. Regions map onto the shell's CSS grid:
 *
 *   menubar        the top strip
 *   viewport       the GL surface and anything drawn over it
 *   internal-gui   PyMOL's right-hand column — the blocks `OrthoLayoutPanel()`
 *                  stacks bottom-up (`layer1/Ortho.cpp:2261-2340`): Executive,
 *                  Wizard, ButMode, Control
 *   external-gui   the bottom dock (feedback + command line + quick buttons)
 *   overlay        dialogs and floating panels
 *   service        no UI of its own; installs behaviour (keys, picking, menus)
 */

import type { ComponentType } from 'react';

export type FeatureRegion =
  'menubar' | 'viewport' | 'internal-gui' | 'external-gui' | 'overlay' | 'service';

export interface FeatureSlot {
  id: string;
  /** Human name, shown in the "not installed" placeholder and in diagnostics. */
  title: string;
  region: FeatureRegion;
  /** Work package that owns `features/<id>/**`. */
  owner: string;
  /** Sort key within the region. */
  order: number;
  /** What the region shows while the directory does not exist. */
  absent: string;
}

