export type FeatureId = (typeof FEATURE_SLOTS)[number]['id'];

/** What `features/<id>/register.ts` must default-export. */
export interface FeatureModule {
  /** Must equal the directory name. Checked at load time. */
  id: string;
  /** The panel rendered in the slot's region. */
  Panel: ComponentType;
  /**
   * Optional: run once when the feature loads, for `service` features that
   * install behaviour instead of rendering. Returns a teardown.
   */
  install?: () => void | (() => void);
}

/* ------------------------------------------------------------------ *
 * Discovery
 * ------------------------------------------------------------------ */

/**
 * Lazy on purpose. An eager glob would make one feature's broken import a blank
 * application; lazily, a failure is confined to its own slot and reported there
 * by the shell's error boundary.
 */
const LOADERS = import.meta.glob('./*/register.ts') as Record<
  string,
  () => Promise<{ default: FeatureModule }>
>;

const BY_ID = new Map<string, () => Promise<{ default: FeatureModule }>>(
  Object.entries(LOADERS).map(([path, loader]) => [path.split('/')[1] ?? path, loader]),
);

const SLOT_BY_ID = new Map(FEATURE_SLOTS.map((slot) => [slot.id, slot]));

/** Directories present that no slot declares — a typo, and it must not be silent. */
export const UNDECLARED_FEATURES: readonly string[] = [...BY_ID.keys()].filter(
  (id) => !SLOT_BY_ID.has(id),
);

export function getSlot(id: string): FeatureSlot | undefined {
  return SLOT_BY_ID.get(id);
}

export function isInstalled(id: string): boolean {
  return BY_ID.has(id);
}

export function loadFeature(id: string): (() => Promise<{ default: FeatureModule }>) | undefined {
  return BY_ID.get(id);
}

export function installedFeatureIds(): readonly string[] {
  return [...BY_ID.keys()].sort();
}

export function slotsForRegion(region: FeatureRegion): readonly FeatureSlot[] {
  return FEATURE_SLOTS.filter((slot) => slot.region === region).sort((a, b) => a.order - b.order);
}
